    # send notification event
    event('notify',{})
elif notify_status=='unknown':
    stop('UNRESOLVED_EFFECT')
# else notify_status=='sent' means effect done, do nothing
prepare_status=status('prepare')
if prepare_status=='not_sent':
    event('prepare',{})
elif prepare_status=='unknown':
    stop('UNRESOLVED_EFFECT')
# else prepare_status=='sent' means effect done, do nothing
